mapper.select:
SELECT RP.MENU_ID , RP.PERMISSION_CODE FROM TB_ROLE_PERMISSION RP INNER JOIN TB_PERMISSION P ON RP.PERMISSION_CODE = P.PERMISSION_CODE INNER JOIN TB_MENU M ON RP.MENU_ID = M.MENU_ID WHERE RP.ROLE_CODE = #{roleCode}
AND P.DATA_STATUS = #{dataStatus} AND M.DATA_STATUS = #{dataStatus}
ORDER BY M.SORT_ORDER, P.SORT_ORDER

mapper.insert:
INSERT INTO TB_PERMISSION (
    PERMISSION_CODE
  , PERMISSION_NAME
  , DATA_STATUS
  , SORT_ORDER
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{permissionCode}
  , #{permissionName}
  , #{dataStatus}
  , #{sortOrder}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_PERMISSION
   SET PERMISSION_NAME = #{permissionName}
     , DATA_STATUS     = #{dataStatus}
     , SORT_ORDER      = #{sortOrder}
     , UPDATED_BY      = #{author}
     , UPDATED_AT      = NOW()
 WHERE PERMISSION_CODE = #{permissionCode}
